#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC Core 17 - Layer 5 bring-up package
#
# Deploys the complete Layer 5 tree under $HOME/vhdl_repo/IP_Cores/PQC/l5/:
#   rtl/         all synthesis RTL (validated in GHDL) + testbenches
#   vivado/      pqc_vivado.tcl   (project, block design, synth, impl, XSA)
#   petalinux/   pqc_petalinux.sh (build, device tree, BOOT.BIN)
#   ps/          pqc_selftest_ps.c (PS launcher, mirrors tb_pqc_top's AXI)
#   STEPS.md, L5_BRINGUP.md, ANALYSIS_ORDER.txt
#
# The RTL is validated: the embedded-ROM self-test reproduces both signatures
# end to end through AXI-Lite transactions in GHDL. The Vivado and PetaLinux
# scripts are correct by construction but were NOT run where this was
# assembled (those tools are not present there), so step through them.
#
# After deploy, start at STEPS.md section 0.
# Expected final board output:
#   PQC L5 SELFTEST PASS kem=95e07091fa5b3cc4 dsa=f93232f7ea2d1575
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC/l5"
  mkdir -p "$DEST/rtl" "$DEST/vivado" "$DEST/petalinux" "$DEST/ps"
